        break
return u"},"charts":[{"type":"stacked_bar","title":"Đóng góp năng lượng theo lớp khoảng cách","x_label":"Lớp tương tác","y_label":"Tỷ phần năng lượng","series":[{"name":"song song","values":[18,24,27,29]},{"name":"xiên","values":[12,16,19,21]},{"name":"vuông góc","values":[7,10,13,15]}],"categories":["L1","L2","L3","L4"]},{"type":"grouped_bar","title":"Sai số theo mật độ mạng","x_label":"Mật độ chuẩn hóa","y_label":"Sai số tương đối","series":[{"name":"lambda = 0.6","values":[0.084,0.061,0.043,0.031]},{"name":"lambda = 1.0","values":[0.112,0.083,0.059,0.044]},{"name":"lambda = 1.4","values":[0.137,0.101,0.075,0.056]}],"categories":["0.5","1.0","1.5","2.0"]},{"type":"line","title":"Năng lượng theo số bước lặp","x_label":"Bước lặp","y_label":"Năng lượng chuẩn hóa","series":[{"name":"mạng dị hướng","values":[1.000,0.782,0.641,0.568,0.541,0.534,0.532]},{"name":"mạng đẳng hướng","values":[1.000,0.811,0.690,0.612,0.579,0.566,0.562]}],"categories":["0","20","40","60","80","100","120"]},{"type":"scatter","title":"Liên hệ giữa độ lệch biên và bán kính tương tác","x_label":"Bán kính tương tác","y_label":"Độ lệch biên","points":[{"x":0.4,"y":0.182},{"x":0.6,"y":0.141},{"x":0.8,"y":0.109},{"x":1.0,"y":0.087},{"x":1.2,"y":0.071},{"x":1.4,"y":0.060}]}],"figure":{"type":"block_diagram","title":"Sơ đồ khối của quy trình tính toán","blocks":["Trường định hướng","Hạt nhân tương tác","Phiếm hàm năng lượng","Bộ giải lặp","Đánh giá hội tụ"],"connections":["Trường định hướng -> Hạt nhân tương tác","Hạt nhân tương tác -> Phiếm hàm năng lượng","Phiếm hàm năng lượng -> Bộ giải lặp","Bộ giải lặp -> Đánh giá hội tụ","Đánh giá hội tụ -> Bộ giải lặp"]},"tables":[{"caption":"Bảng 1. Tham số của các cấu hình mạng","columns":["Cấu hình","Mật độ","lambda","rho","Số nút"],"rows":[["A","0.5","0.6","2.2","480"],["B","1.0","1.0","2.6","960"],["C","1.5","1.4","3.0","1440"],["D","2.0","1.8","3.4","1920"]]},{"caption":"Bảng 2. Chỉ số hội tụ và ổn định","columns":["Cấu hình","Năng lượng cuối","Số bước","Độ lệch biên","Chỉ số ổn định"],"rows":[["A","0.532","120","0.182","0.76"],["B","0.487","145","0.121","0.84"],["C","0.451","170","0.087","0.91"],["D","0.438","190","0.060","0.94"]]}],"citations":["[30–34]"]},{"heading":"7. Hạn chế","paragraphs":["Mô hình hiện tại giả định biến dạng nhỏ và trường hướng được biết trước. Khi xuất hiện tái định hướng mạnh, hạt nhân cần được cập nhật đồng thời với nghiệm. Ngoài ra, điều kiện biên tuần hoàn có thể làm giảm các hiệu ứng mép trong miền hữu hạn.","Đánh giá hiện mới tập trung vào mạng hai chiều và hạt nhân đơn điệu. Việc mở rộng sang mạng ba chiều, tương tác có dấu đổi và biến thiên nhiệt độ cần những ước lượng mới [35–38]."],"citations":["[35–38]"]},{"heading":"8. Kết luận","paragraphs":["Một mô hình thế năng phi địa phương cho mạng vật liệu dị hướng đã được thiết lập. Phân tích lý thuyết chứng minh sự tồn tại của trạng thái cực tiểu và đưa ra đánh giá ổn định. Các phép đo số xác nhận ảnh hưởng có hệ thống của bán kính tương tác, mật độ mạng và trường định hướng.","Trong hướng tiếp theo, chúng tôi sẽ kết hợp trường hướng động với quy luật biến dạng lớn, đồng thời khảo sát bộ giải đa cấp nhằm giảm chi phí cho mạng có nhiều lớp tương tác [39, 40]."],"citations":["[39, 40]"]}],"references":[{"id":1,"text":"Vũ Tấn Lộc, Phạm Gia Hân. Phiếm hàm năng lượng trên mạng dị hướng. Kỷ yếu Cơ học Lam Nguyên, 2013, 6: 11–24."},{"id":2,"text":"Đỗ Hải Yến, Bùi Quang Thái. Tương tác tầm trung trong vật liệu mạng. Tạp chí Vật chất Vân Hà, 2014, 9: 37–49."},{"id":3,"text":"Ngô Minh Triết. Toán tử hạt nhân suy giảm và cấu trúc vi mô. Chuyên san Tính toán Hạ Nguyên, 2012, 4: 5–19."},{"id":4,"text":"Lâm Ngọc Phúc, Trịnh Uyên Nhi. Mô hình liên kết định hướng. Tạp chí Cơ học Lam Nguyên, 2015, 8: 51–66."},{"id":5,"text":"Phan Đức Thành. Biến phân trên mạng hữu hạn. Kỷ yếu Toán ứng dụng Vân Hà, 2011, 3: 72–84."},{"id":6,"text":"Mai Thanh Vân, Lê Quốc Bảo. Đáp ứng đàn hồi của mạng không đồng nhất. Tạp chí Vật liệu Hạ Nguyên, 2016, 10: 18–31."},{"id":7,"text":"Hoàng Gia Minh. Hạt nhân tích phân cho vật liệu dị hướng. Chuyên san Mô hình Lam Nguyên, 2017, 5: 40–55."},{"id":8,"text":"Trần Nguyên Kỳ, Nguyễn Bích Liên. Ổn định năng lượng trong mạng rời rạc. Kỷ yếu Cơ học Vân Hà, 2013, 7: 26–39."},{"id":9,"text":"Đặng Khánh Toàn. Phân tích khoảng tương tác hữu hiệu. Tạp chí Tính toán Hạ Nguyên, 2018, 11: 9–22."},{"id":10,"text":"Phạm Ngọc Diệp. Định hướng cục bộ trong cấu trúc mạng. Tạp chí Vật chất Lam Nguyên, 2016, 12: 44–58."},{"id":11,"text":"Lê Thùy Dương, Võ Minh Khang. Cưỡng bức của dạng toàn phương. Kỷ yếu Giải tích Vân Hà, 2014, 2: 61–74."},{"id":12,"text":"Bùi An Nhiên. Mô phỏng thế năng đa lớp. Chuyên san Cơ học Hạ Nguyên, 2019, 6: 13–29."},{"id":13,"text":"Nguyễn Khôi Nguyên. Sai số rời rạc trong mô hình phi địa phương. Tạp chí Lam Nguyên, 2017, 9: 33–47."},{"id":14,"text":"Đỗ Hoài Nam, Trương Yến Chi. Tensor hướng và đáp ứng vĩ mô. Tạp chí Vân Hà, 2015, 14: 21–36."},{"id":15,"text":"Lý Thanh Hà. Định lý tồn tại cho mạng liên thông. Kỷ yếu Phương trình Hạ Nguyên, 2012, 8: 3–17."},{"id":16,"text":"Phan Minh Châu. Không gian thương của trường biến dạng. Tạp chí Giải tích Lam Nguyên, 2016, 7: 55–68."},{"id":17,"text":"Võ Quốc Huy. Tính nửa liên tục của phiếm hàm mạng. Chuyên san Vân Hà, 2013, 5: 28–42."},{"id":18,"text":"Nguyễn Tường Vi, Lê Hà Phương. Cực tiểu năng lượng với biên hỗn hợp. Tạp chí Cơ học Hạ Nguyên, 2018, 9: 48–62."},{"id":19,"text":"Trần Hoàng Phúc. Điều kiện dương xác định cho hạt nhân. Kỷ yếu Toán tính Lam Nguyên, 2015, 4: 16–30."},{"id":20,"text":"Mai Quang Vinh. Liên thông định hướng trong mạng tinh thể. Tạp chí Vật liệu Vân Hà, 2017, 13: 70–83."},{"id":21,"text":"Đinh Bảo Trâm. Đánh giá phổ của toán tử tương tác. Chuyên san Cơ học Lam Nguyên, 2019, 10: 7–20."},{"id":22,"text":"Lê Minh Tân. Thế năng phi địa phương và chuyển vị bất biến. Tạp chí Hạ Nguyên, 2014, 6: 35–48."},{"id":23,"text":"Ngô Bảo Khánh. Phân hoạch vành trong tổng suy giảm. Kỷ yếu Giải tích Vân Hà, 2016, 3: 25–38."},{"id":24,"text":"Phạm Uyên Trang. Bất đẳng thức cho trường mạng. Tạp chí Lam Nguyên, 2013, 9: 52–65."},{"id":25,"text":"Đào Minh Đức. Hội tụ của chuỗi khoảng cách. Chuyên san Toán ứng dụng Hạ Nguyên, 2015, 2: 14–27."},{"id":26,"text":"Vũ Ngọc Anh. Ước lượng chuẩn cho dạng toàn phương. Tạp chí Vân Hà, 2018, 8: 39–53."},{"id":27,"text":"Trịnh Hải Long. Biên hữu hạn trong mô hình mạng. Kỷ yếu Cơ học Lam Nguyên, 2017, 11: 63–76."},{"id":28,"text":"Bùi Thùy An. Hạt nhân suy giảm theo hướng. Tạp chí Vật chất Hạ Nguyên, 2016, 5: 12–26."},{"id":29,"text":"Hoàng Minh Khoa. Nghiệm cực tiểu và điều kiện biên. Chuyên san Vân Hà, 2019, 7: 46–59."},{"id":30,"text":"Lê Quang Hòa. Thuật toán lặp cho phiếm hàm mạng. Tạp chí Tính toán Lam Nguyên, 2014, 10: 18–32."},{"id":31,"text":"Nguyễn Hà My. Tốc độ giảm năng lượng trong giải số. Kỷ yếu Hạ Nguyên, 2015, 6: 41–54."},{"id":32,"text":"Phan Thanh Tùng. Cấu hình mạng vuông biến dạng. Tạp chí Vân Hà, 2018, 12: 5–18."},{"id":33,"text":"Đỗ Minh Quân. Đo lường sai số chuẩn hóa. Chuyên san Lam Nguyên, 2016, 8: 29–43."},{"id":34,"text":"Trần Bảo Ngọc. Phân tích độ nhạy của bán kính tương tác. Tạp chí Vật liệu Hạ Nguyên, 2017, 4: 57–71."},{"id":35,"text":"Lê Gia Bảo. Biến dạng lớn trong mạng dị hướng. Kỷ yếu Cơ học Vân Hà, 2019, 9: 22–35."},{"id":36,"text":"Võ Thanh Hà. Tái định hướng và hạt nhân động. Tạp chí Lam Nguyên, 2018, 6: 64–78."},{"id":37,"text":"Mai Đức Anh. Hiệu ứng mép của miền hữu hạn. Chuyên san Hạ Nguyên, 2015, 7: 30–44."},{"id":38,"text":"Nguyễn Thảo Linh. Mạng ba chiều và tương tác có dấu. Tạp chí Vân Hà, 2019, 13: 11–25."},{"id":39,"text":"Phạm Khánh Linh. Bộ giải đa cấp cho mạng nhiều lớp. Kỷ yếu Tính toán Lam Nguyên, 2016, 5: 36–50."},{"id":40,"text":"Trương Minh Kha. Ghép trường hướng với biến dạng động. Tạp chí Cơ học Hạ Nguyên, 2018, 10: 73–87."}]}}
